<?php
$waiting=packageRows("p.status_paket='Diterima'");
$active=(int)scalar("SELECT COUNT(*) FROM alokasi_rak WHERE status_alokasi='Aktif'");
$history=rows('SELECT a.*,p.nama_penerima,p.berat_kg,r.kode_rak,t.nama_petugas FROM alokasi_rak a JOIN paket p USING(no_resi) JOIN rak_gudang r USING(id_rak) JOIN petugas t USING(id_petugas) ORDER BY waktu_masuk DESC,id_alokasi DESC');
heading('','Penempatan','Pilih paket yang diterima, lalu tentukan rak penyimpanannya.',modalButton('Pindahkan rak','pindah-form','swap','secondary').modalButton('Tempatkan paket','alokasi-form','in'));
stats([['Menunggu penempatan',num(count($waiting)),'Paket diterima dan belum memiliki rak','box','orange'],['Paket di rak',num($active),'Penempatan yang masih aktif','rack','green']]);
?>
<section class="panel section-gap"><div class="panel-head"><div><h2>Antrean penempatan <span class="count-pill"><?=count($waiting)?></span></h2><p>Paket yang sudah diterima dan belum memiliki rak</p></div><?=linkButton('Terima paket baru',url('paket',['open'=>'paket-form']),'plus','secondary small')?></div><?php if(!$waiting)emptyState('Semua paket sudah tertata','Paket baru akan muncul di sini setelah dicatat.');else packageTable($waiting);?></section>
<section class="panel"><div class="panel-head"><div><h2>Riwayat alokasi rak</h2><p>Catatan penempatan tetap tersimpan setelah paket berpindah</p></div><span class="count-pill"><?=count($history)?> aktivitas</span></div><?php if(!$history):emptyState('Belum ada penempatan');else: ?><div class="table-wrap"><table><thead><tr><th>Paket</th><th>Rak</th><th>Berat</th><th>Petugas</th><th>Waktu penempatan</th><th>Alokasi</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><a class="resi" href="<?=e(url('paket',['resi'=>$h['no_resi']]))?>"><?=e($h['no_resi'])?></a><span class="cell-sub"><?=e($h['nama_penerima'])?></span></td><td><span class="rack-code"><?=icon('rack')?><?=e($h['kode_rak'])?></span></td><td><?=kg($h['berat_kg'])?></td><td><?=e($h['nama_petugas'])?></td><td class="muted"><?=e(stamp($h['waktu_masuk']))?></td><td><?=badge($h['status_alokasi'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php allocationDialog('alokasi');allocationDialog('pindah'); ?>
